import { readFile, writeFile, mkdir, copyFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import path from 'node:path'

// Each application keeps a self-contained generated file for independent builds.
const frontend = fileURLToPath(new URL('../', import.meta.url))
const workspace = path.resolve(frontend, '../..')
const source = await readFile(path.join(frontend, 'src/shared/ui/teamspace.css'), 'utf8')
const tokens = source.slice(source.indexOf(':root {'), source.indexOf('\n}\n') + 3)
const fontSource = path.join(frontend, 'node_modules/@fontsource/inter')
const fontFaces = []
const fontFiles = new Set()
for (const weight of [400, 500, 600, 700]) {
  const css = await readFile(path.join(fontSource, `${weight}.css`), 'utf8')
  for (const face of css.matchAll(/@font-face\s*\{[^}]+\}/g)) {
    const filename = face[0].match(/inter-(?:cyrillic(?:-ext)?|latin(?:-ext)?)-\d+-normal\.woff2/)?.[0]
    if (!filename) continue
    fontFiles.add(filename)
    fontFaces.push(face[0].replace(/src:[^;]+;/, `src: url('./fonts/${filename}') format('woff2');`))
  }
}
const targets = [
  'iform/frontend', 'sd/workspace-sd-front', 'odo/workspace-odo-front',
  'growy/workspace-growy-front', 'workspace/workspace-mail',
  'workspace/workspace-front/deploy/whiteboard/source/frontend',
  'workspace/workspace-front/deploy/mail/source',
]
for (const target of targets) {
  const styles = path.join(workspace, target, 'src/styles')
  await mkdir(styles, { recursive: true })
  await writeFile(path.join(styles, 'teamspace-tokens.css'), `/* Generated by workspace-front/scripts/sync-teamspace-theme.mjs. */\n${tokens}\n`)
  await mkdir(path.join(styles, 'fonts'), { recursive: true })
  for (const filename of fontFiles) await copyFile(path.join(fontSource, 'files', filename), path.join(styles, 'fonts', filename))
  await copyFile(path.join(fontSource, 'LICENSE'), path.join(styles, 'fonts', 'Inter-LICENSE.txt'))
  await writeFile(path.join(styles, 'teamspace-fonts.css'), `/* Generated Inter webfonts. Cyrillic, Kazakh and Latin character sets. */\n${fontFaces.join('\n')}\n`)
  console.log(`Theme synchronized: ${target}`)
}
